<script setup lang="ts">import {onMounted,ref} from 'vue';const data=ref<any>({});const h=()=>({Authorization:`Bearer ${localStorage.getItem('token')}`});onMounted(async()=>{const [a,b]=await Promise.all([fetch('/api/admin/accounts',{headers:h()}),fetch('/api/admin/billing/summary',{headers:h()})]);const ac=await a.json(),s=await b.json();data.value={active:ac.filter((x:any)=>x.active).length,...s}})</script>
<template><div class="hero"><div><p class="eyebrow">Admin</p><h1>Dashboard</h1></div></div><div class="stats"><div class="card"><small>Aktív ügyfelek</small><strong>{{data.active||0}}</strong></div><div class="card"><small>Számlázatlan küldemények</small><strong>{{data.shipmentCount||0}}</strong></div><div class="card"><small>Ügyfélár összesen</small><strong>{{data.totalCustomerPrice||0}} {{data.currency}}</strong></div><div class="card"><small>Becsült árrés</small><strong>{{data.totalMargin||0}} {{data.currency}}</strong></div></div></template>
